steps.codeExample:
#include <iostream>

int main() {
    for (int i = 0; i < 5; i++) {
        if (i == 2) continue; // pula o 2
        if (i == 4) break;    // para no 4
        std::cout << i << "\n";
    }

    int n = 3;
    while (n > 0) {
        std::cout << n << "\n";
        n--;
    }
    return 0;
}

